def flatten_json(nested_json):
    """
    Flattens a nested JSON object into a dotted-key dictionary.

    Args:
        nested_json (dict): The input JSON object to be flattened.

    Returns:
        dict: A dictionary with dotted keys representing the flattened JSON.
    """
    def _flatten(json, prefix=""):
        result = {}
        for key, value in json.items():
            new_key = f"{prefix}{key}" if prefix else key
            if isinstance(value, dict):
                # If the value is a dictionary, recursively call _flatten with the updated prefix
                result.update(_flatten(value, new_key + "."))
            elif len(new_key) <= 50:
                # If the key length does not exceed 50 characters, add it to the result
                result[new_key] = value
        return result

    return _flatten(nested_json)

# Example usage
nested_json = {
    "name": "John",
    "age": 30,
    "address": {
        "street": "123 Main St",
        "city": "New York",
        "state": "NY"
    },
    "interests": ["reading", "hiking", "coding"]
}

flattened_json = flatten_json(nested_json)
print(flattened_json)

