class Database:
    def __init__(self, db_name):
        self.conn = None
        self.cursor = None
        self.db_name = db_name

    def connect(self):
        try:
            self.conn = sqlite3.connect(self.db_name)
            self.cursor = self.conn.cursor()
            return True
        except sqlite3.Error as e:
            print(e)
            return False

    def disconnect(self):
        if self.conn:
            self.conn.close()

    def execute_query(self, query, params=None):
        if not self.conn:
            raise Exception("Database is not connected")

        if params:
            try:
                self.cursor.execute(query, params)
            except sqlite3.Error as e:
                print(e)

        else:
            self.cursor.execute(query)

        return self.cursor.fetchall()

    def fetch_json(self, query, params=None):
        if not self.conn:
            raise Exception("Database is not connected")

        if params:
            try:
                result = self.execute_query(query, params)
            except sqlite3.Error as e:
                print(e)
                return []
            else:
                rows = [dict(zip([desc[0] for desc in self.cursor.description], row)) for row in result]
                return dumps(rows, indent=4)

        else:
            try:
                result = self.execute_query(query)
            except sqlite3.Error as e:
                print(e)
                return []

            rows = [dict(zip([desc[0] for desc in self.cursor.description], row)) for row in result]
            return dumps(rows, indent=4)

